import re
import asyncio
from urllib.parse import urljoin

async def act(page):
    """
    From the current Manage Pages grid, find the row for "404 Not Found",
    navigate to its edit page (by extracting an edit URL if present, otherwise clicking
    the title cell to navigate), update the Page Title to the requested string,
    and click Save.
    """

    new_title = "Bruh bro you clicked the wrong page"

    # Ensure the grid is loaded
    await page.wait_for_load_state("domcontentloaded")
    await asyncio.sleep(0.5)

    # Locate the row containing the cell with the exact name "404 Not Found"
    rows = page.get_by_role("row").filter(has=page.get_by_role("cell", name="404 Not Found"))
    if await rows.count() == 0:
        raise RuntimeError('Could not find a row containing a cell with the name "404 Not Found"')

    row = rows.first

    # Try to extract an edit URL from common attributes (onclick) or a link inside the row
    edit_href = None

    onclick_attr = await row.get_attribute("onclick")
    if onclick_attr:
        m = re.search(r"setLocation\(['\"]([^'\"]+)['\"]\)", onclick_attr)
        if m:
            edit_href = m.group(1)
        else:
            m2 = re.search(r"['\"](\/index\.php\/admin\/[^'\"]+)['\"]", onclick_attr)
            if m2:
                edit_href = m2.group(1)
            else:
                m3 = re.search(r"['\"](\/[^'\"]*cms_page[^'\"]*)['\"]", onclick_attr, re.IGNORECASE)
                if m3:
                    edit_href = m3.group(1)

    # If not found on the row, try the title cell's onclick
    if not edit_href:
        title_cell = row.get_by_role("cell", name="404 Not Found")
        if await title_cell.count() > 0:
            onclick_cell = await title_cell.first.get_attribute("onclick")
            if onclick_cell:
                m = re.search(r"setLocation\(['\"]([^'\"]+)['\"]\)", onclick_cell)
                if m:
                    edit_href = m.group(1)
                else:
                    m2 = re.search(r"['\"](\/index\.php\/admin\/[^'\"]+)['\"]", onclick_cell)
                    if m2:
                        edit_href = m2.group(1)

    # If still not found, search for links inside the row
    if not edit_href:
        links_in_row = row.get_by_role("link")
        if await links_in_row.count() > 0:
            href_found = None
            total = await links_in_row.count()
            for i in range(min(50, total)):
                href = await links_in_row.nth(i).get_attribute("href")
                if href:
                    if any(k in href for k in ("edit", "cms_page", "admin", "page_id", "no-route")):
                        href_found = href
                        break
                    if not href_found:
                        href_found = href
            if href_found:
                edit_href = href_found

    # If no href, as a last resort click the title cell to navigate (this will be followed by interacting on the edit page)
    if not edit_href:
        # clicking will navigate away; perform click and then continue to interact on the new page
        # Use the title_cell found above (if not found, locate again)
        title_cell = page.get_by_role("cell", name="404 Not Found")
        if await title_cell.count() == 0:
            raise RuntimeError('Could not find the title cell to click for "404 Not Found"')
        await title_cell.first.click()
        await page.wait_for_load_state("domcontentloaded")
    else:
        # Normalize and go to the edit URL
        edit_url = urljoin(page.url, edit_href)
        await page.goto(edit_url)
        await page.wait_for_load_state("domcontentloaded")

    # Small pause to allow edit form to render
    await asyncio.sleep(0.8)

    # Locate the Page Title textbox (accessibility-first)
    title_field = page.get_by_role("textbox", name="Page Title")
    if await title_field.count() == 0:
        title_field = page.get_by_label("Page Title")

    if await title_field.count() == 0:
        # Heuristic fallback: scan textboxes for attributes containing 'title'
        textboxes = page.get_by_role("textbox")
        filled = False
        total_txt = await textboxes.count()
        for i in range(min(200, total_txt)):
            tb = textboxes.nth(i)
            try:
                aria = await tb.get_attribute("aria-label")
            except Exception:
                aria = None
            if aria and "title" in aria.lower():
                await tb.fill(new_title)
                filled = True
                break
            try:
                name_attr = await tb.get_attribute("name")
            except Exception:
                name_attr = None
            if name_attr and "title" in name_attr.lower():
                await tb.fill(new_title)
                filled = True
                break
            try:
                id_attr = await tb.get_attribute("id")
            except Exception:
                id_attr = None
            if id_attr and "title" in id_attr.lower():
                await tb.fill(new_title)
                filled = True
                break
        if not filled:
            raise RuntimeError('Could not find the "Page Title" textbox on the CMS page edit form')
    else:
        await title_field.first.fill(new_title)

    # Locate Save button (try common accessible names)
    save_btn = page.get_by_role("button", name="Save Page")
    if await save_btn.count() == 0:
        save_btn = page.get_by_role("button", name="Save")
    if await save_btn.count() == 0:
        save_btn = page.get_by_role("button", name="Save CMS Page")

    if await save_btn.count() == 0:
        # fallback: scan buttons and pick one whose aria-label contains 'save'
        btns = page.get_by_role("button")
        total_btns = await btns.count()
        for i in range(min(200, total_btns)):
            b = btns.nth(i)
            try:
                aria = await b.get_attribute("aria-label")
            except Exception:
                aria = None
            if aria and "save" in aria.lower():
                save_btn = b
                break

    if await save_btn.count() == 0:
        raise RuntimeError('Could not find a Save button on the CMS page edit form')

    await save_btn.first.click()

    # Wait for save to complete
    try:
        await page.wait_for_load_state("networkidle", timeout=10000)
    except Exception:
        await asyncio.sleep(1)

    print('Updated 404 page title to:', new_title)

